/* Night-blue ANSI logo rendered as text. Presentation only; data comes from ansi-logo-data.js (generated by art/ansi/make-art.py). */
(function(root){
 const data=root.NightlinkLogoData||(typeof require==='function'?require('./ansi-logo-data.js'):null);
 // Builds <pre> rows of classed spans with textContent only (CSP style-src 'self', no inline styles or markup).
 function buildArt(rows,className){
  const pre=document.createElement('pre');pre.className=className;pre.setAttribute('aria-hidden','true');
  rows.forEach((row,index)=>{if(index)pre.append('\n');for(const [color,text]of row){if(color===null){pre.append(text);continue;}const span=document.createElement('span');span.className='ansi-logo-'+color;span.textContent=text;pre.append(span);}});
  return pre;
 }
 function create(variant='logo',label='Nightlink'){
  const figure=document.createElement('div');figure.className='ansi-logo ansi-logo-'+variant+'-card';figure.setAttribute('role','img');figure.setAttribute('aria-label',label);
  figure.append(buildArt(variant==='wordmark'?data.wordmark:data.logo,'ansi-logo-art'));
  return figure;
 }
 function mountBrand(){
  const brand=document.querySelector('aside .brand');if(!brand||brand.querySelector('.ansi-logo-wordmark'))return;
  for(const node of [...brand.childNodes])if(node.nodeType===3)node.remove();
  const mark=buildArt(data.wordmark,'ansi-logo-art ansi-logo-wordmark');
  brand.setAttribute('aria-label','Nightlink');brand.append(mark);
 }
 function mountConnection(){
  const sheet=document.querySelector('.ble-sheet'),heading=sheet?.querySelector(':scope > .dialog-heading');
  if(!heading||sheet.querySelector('.ansi-logo'))return;
  const logo=create('logo','Nightlink logo');logo.classList.add('ansi-logo-connect');heading.after(logo);
 }
 const api={data,create,mountBrand,mountConnection};
 if(typeof module==='object'&&module.exports){module.exports=api;return;}
 root.NightlinkLogo=api;mountBrand();
 // Mounted after every script has built the connection dialog so the logo leads its controls.
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mountConnection);else mountConnection();
})(typeof window==='object'?window:globalThis);
